# Screener ensemble (maximum five active factors; all directions positive).
FACTORS = {"lowvol_rev1": 0.55, "clv": 0.18, "peer5": 0.13, "mom20": 0.10, "overnight_intraday_rev": 0.04}
REBALANCE_EVERY = 10
MIN_WEIGHT, MAX_WEIGHT = 0.02, 0.14
_calls = 0

def cross_rank(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1) / n if n > 1 else 0.5
    return out

def project(raw):
    # Bounded water-filling; produces a complete, non-negative, unit-sum target.
    fixed = {}
    w = {s: max(float(raw.get(s, 0.5)), 1e-8) for s in UNIVERSE}
    for _ in range(30):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        z = sum(w[s] for s in free)
        trial = {s: rem * w[s] / z if z else rem / len(free) for s in free}
        changed = False
        for s, q in trial.items():
            if q < MIN_WEIGHT:
                fixed[s] = MIN_WEIGHT; changed = True
            elif q > MAX_WEIGHT:
                fixed[s] = MAX_WEIGHT; changed = True
        if not changed:
            result = dict(fixed); result.update(trial)
            z = sum(result.values())
            return {s: result[s] / z for s in UNIVERSE}
    result = {s: fixed.get(s, MIN_WEIGHT) for s in UNIVERSE}
    z = sum(result.values())
    return {s: v / z for s, v in result.items()}

@register_hook
def cross_asset_strategy():
    global _calls
    _calls += 1
    if _calls != 1 and (_calls - 1) % REBALANCE_EVERY != 0:
        return
    factors = {k: {} for k in FACTORS}
    vols, mom = {}, {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        o = np.asarray(df["open"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        if np.any(~np.isfinite(c[-30:])) or np.any(c[-30:] <= 0):
            continue
        daily = c[1:] / c[:-1] - 1.0
        sigma = max(float(np.std(daily[-20:])), 0.008)
        vols[symbol] = sigma
        factors["lowvol_rev1"][symbol] = -daily[-1] / sigma
        # Risk-adjusted 20-day momentum, smoothed only by its volatility scale.
        factors["mom20"][symbol] = (c[-1] / c[-21] - 1.0) / (sigma + 0.01)
        mom[symbol] = factors["mom20"][symbol]
        span = h[-1] - l[-1]
        factors["clv"][symbol] = (c[-1] - l[-1]) / span if np.isfinite(span) and span > 0 else 0.5
        # A conservative total overnight/intraday reversal proxy from OHLC.
        overnight = o[-1] / c[-2] - 1.0
        intraday = c[-1] / o[-1] - 1.0 if o[-1] > 0 else 0.0
        factors["overnight_intraday_rev"][symbol] = -(overnight + intraday) / sigma
    if len(vols) < 8:
        return
    # Leave-one-out five-day peer-median lead-lag.
    five = {s: c5 for s, c5 in []}
    for symbol in list(vols):
        df = get_stock_daily_data(symbol=symbol, days=10)
        if df is not None and len(df) >= 6:
            close = np.asarray(df.sort_values("date")["close"], dtype=float)
            five[symbol] = close[-1] / close[-6] - 1.0
    for symbol in vols:
        peers = [five[t] for t in vols if t != symbol and t in five]
        factors["peer5"][symbol] = five.get(symbol, 0.0) - (float(np.median(peers)) if peers else 0.0)
    ranks = {k: cross_rank(v) for k, v in factors.items()}
    score = {s: sum(FACTORS[k] * ranks[k][s] for k in FACTORS) for s in UNIVERSE}
    breadth = np.mean([mom[s] > 0 for s in mom])
    defensive = {"XAU", "US10Y", "CN10Y"}
    avg_inv = np.mean([1.0 / v for v in vols.values()])
    raw = {}
    for symbol in UNIVERSE:
        invtilt = min((1.0 / vols[symbol]) / avg_inv, 1.8) if symbol in vols else 1.0
        # Medium-high risk / weak breadth: tilt, rather than reduce gross exposure.
        risk_tilt = 1.18 if breadth < 0.50 and symbol in defensive else (0.93 if breadth < 0.50 else 1.0)
        raw[symbol] = max(score[symbol], 0.05) * (0.94 + 0.06 * invtilt) * risk_tilt
    rebalance_to_weights(project(raw))

