           "stress": 0.10, "residual": 0.08, "volume": 0.06}
REBALANCE_EVERY = 10
MIN_WEIGHT, MAX_WEIGHT = 0.02, 0.14
_calls = 0


def rank_map(x):
    valid = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(valid) > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    elif valid:
        out[valid[0][0]] = 1.0
    return out


def bounded(raw):
