        span = h[-1] - l[-1]
        raw["clv"][symbol] = -(c[-1] - o[-1]) / span if np.isfinite(span) and span > 0 else 0.0
        stress = min(2.0, max(0.5, abs(ret[-1]) / sig))
        raw["stress"][symbol] = (-ret[-1] / sig) * stress
        if "volume" in df.columns:
            v = np.asarray(df["volume"], float); med = np.nanmedian(v[-21:])
            amp = v[-1] / med if np.isfinite(v[-1]) and v[-1] > 0 and med > 0 else 1.0
