import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = 0.035, 0.16
FACTOR_W = {
    "cluster": .20, "volume_shock": .14, "intraday": .12,
    "volshock": .12, "volscaled": .10, "vixstress": .10,
    "macro": .09, "volume_disp": .08, "momentum": .05
}
CLUSTERS = {
    "equity": {"000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX"},
    "commodity": {"XAU", "COPPER", "WTI"}, "crypto": {"BTC", "ETH"},
    "rates": {"US10Y", "CN10Y"}}
_day = 0
_previous = None


def cs_rank(values):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.) / len(good)
    return out


def bounded(raw):
    # Projection onto the full-investment simplex with practical concentration bounds.
    w = {s: max(float(raw.get(s, 1.0)), 1e-12) for s in UNIVERSE}
    fixed = set()
    for _ in range(30):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        total = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / max(total, 1e-12)
        hit = {s for s in free if w[s] < MIN_W or w[s] > MAX_W}
        if not hit:
            break
        for s in hit:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed |= hit
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return

    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=270)
        if df is None or len(df) < 160:
            continue
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)
        open_ = np.asarray(df["open"], dtype=float)
        volume = np.nan_to_num(np.asarray(df["volume"], dtype=float), nan=0.0)
        if len(close) < 160 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            continue
        ret = close[1:] / close[:-1] - 1.0
        overnight = close[1:] / np.maximum(open_[1:], 1e-12) - 1.0
        data[symbol] = {"r": ret, "on": overnight,
                        "h3": np.prod(1 + ret[-3:]) - 1,
                        "h5": np.prod(1 + ret[-5:]) - 1,
                        "h10": np.prod(1 + ret[-10:]) - 1,
                        "h20": np.prod(1 + ret[-20:]) - 1,
                        "h120": np.prod(1 + ret[-120:]) - 1,
                        "v5": max(np.std(ret[-5:]), .006),
                        "v20": max(np.std(ret[-20:]), .006),
                        "v60": max(np.std(ret[-60:]), .006),
                        "vr": np.mean(volume[-5:]) / max(np.mean(volume[-20:]), 1e-12)}
    if len(data) < 10:
        return

    symbols = list(data)
    med = {k: np.median([data[s][k] for s in symbols]) for k in ("h3", "h5", "h10", "h20")}
    factors = {k: {} for k in FACTOR_W}
    for s in symbols:
        x = data[s]
        scale = x["v20"] * np.sqrt(20) + .015
        cluster = next((name for name, members in CLUSTERS.items() if s in members), None)
        peers = [data[t]["r"] for t in symbols if t in CLUSTERS.get(cluster, set())]
        n = min(3, len(x["r"]))
        peer = np.median([a[-n:] for a in peers], axis=0) if peers else np.zeros(n)
        factors["cluster"][s] = -np.sum(x["r"][-n:] - peer) / (x["v20"] + 1e-5)
        factors["volume_shock"][s] = (med["h3"] - x["h3"]) / (x["v5"] + .01) * np.clip(x["vr"], .5, 2.)
        # Intraday-normalized reversal, using the latest completed sessions only.
        intraday = np.mean(x["on"][-3:])
        factors["intraday"][s] = -intraday / (x["v5"] + .01)
        factors["volshock"][s] = (med["h3"] - x["h3"]) / (x["v5"] + .01) * np.clip(x["v5"] / x["v60"], .6, 1.7)
        factors["volscaled"][s] = (med["h5"] - x["h5"]) / scale
        factors["vixstress"][s] = (med["h10"] - x["h10"]) / (x["v20"] * np.sqrt(10) + .02)
        factors["volume_disp"][s] = (med["h20"] - x["h20"]) / scale * np.clip(x["vr"], .6, 1.6)
        factors["momentum"][s] = x["h20"] / (x["v20"] * np.sqrt(20) + .02)

    bench = data.get("SPX", {}).get("r")
    for s in symbols:
        x = data[s]
        if bench is not None and s != "SPX":
            n = min(60, len(x["r"]), len(bench))
            beta = np.cov(x["r"][-n:], bench[-n:])[0, 1] / max(np.var(bench[-n:]), 1e-8)
            residual = np.sum(x["r"][-10:] - beta * bench[-10:])
        else:
            residual = 0.0
        factors["macro"][s] = -residual / (x["v20"] * np.sqrt(10) + .015)

    ranks = {k: cs_rank(v) for k, v in factors.items()}
    breadth = np.mean([data[s]["h120"] > 0 for s in symbols])
    if breadth < .50:
        ranks["momentum"] = {s: .5 for s in UNIVERSE}
    score = {s: sum(FACTOR_W[k] * ranks[k].get(s, .5) for k in FACTOR_W) for s in UNIVERSE}
    if _previous is not None:
        score = {s: .5 * score[s] + .5 * _previous[s] for s in UNIVERSE}
    _previous = score.copy()

    high_risk = np.median([data[s]["v20"] for s in symbols]) > .018 or breadth < .50
    inv_mean = np.mean([1.0 / data[s]["v20"] for s in symbols])
    raw = {}
    for s in UNIVERSE:
        x = data.get(s, {"v20": .02, "h120": 0.0})
        invvol = (1.0 / x["v20"]) / max(inv_mean, 1e-12) if s in data else 1.0
        raw[s] = max(score[s], .12) * (.90 + .10 * min(invvol, 1.25))
        if high_risk and s in DEFENSIVE:
            raw[s] *= 2.0
        if high_risk and x["h120"] < -.10:
            raw[s] *= .75
    rebalance_to_weights(bounded(raw))

