        data[s] = {"r": r, "h5": np.prod(1+r[-5:])-1, "h10": np.prod(1+r[-10:])-1,
                   "h20": np.prod(1+r[-20:])-1, "h60": np.prod(1+r[-60:])-1,
                   "h120": np.prod(1+r[-120:])-1, "v20": max(np.std(r[-20:]), .006),
                   "v60": max(np.std(r[-60:]), .006)}
    if len(data) < 10:
        return
    med = {k: np.median([data[s][k] for s in data]) for k in ("h5", "h10", "h20", "h60")}
    fac = {k: {} for k in FACTOR_W}
    for s, x in data.items():
        cluster = next((k for k, members in CLUSTERS.items() if s in members), None)
        peers = [data[t]["r"][-10:] for t in data if t in CLUSTERS.get(cluster, set())]
        peer = np.median(peers, axis=0) if peers else np.zeros(10)
        fac["cluster"][s] = -np.sum(x["r"][-5:] - peer[-5:]) / (x["v20"] + .01)
        fac["dispersion"][s] = (med["h10"] - x["h10"]) / (x["v20"] * np.sqrt(10) + .02)
        fac["macro"][s] = (med["h20"] - x["h20"]) / (x["v60"] * np.sqrt(20) + .02)
        fac["medium_cluster"][s] = -np.sum(x["r"][-20:] - peer[-10:].mean()) / (x["v20"] * 2 + .02)
        fac["volscaled"][s] = (med["h5"] - x["h5"]) / (x["v20"] * np.sqrt(5) + .02)
        fac["smooth"][s] = -(x["h5"]*.5 + x["h10"]*.3 + x["h20"]*.2) / (x["v20"] * np.sqrt(20) + .02)
        fac["momentum"][s] = .6 * x["h60"] / (x["v60"] + .01) + .4 * x["h120"] / (x["v60"] + .01)
    rr = {k: ranks(v) for k, v in fac.items()}
    score = {s: sum(FACTOR_W[k] * rr[k].get(s, .5) for k in FACTOR_W) for s in UNIVERSE}
    if _previous is not None:
        score = {s: .55 * score[s] + .45 * _previous[s] for s in UNIVERSE}
    _previous = score.copy()
    breadth = np.mean([data[s]["h120"] > 0 for s in data])
    high_risk = np.median([data[s]["v20"] for s in data]) > .018 or breadth < .50
    invmean = np.mean([1.0 / data[s]["v20"] for s in data])
    raw = {}
    for s in UNIVERSE:
        x = data.get(s, {"v20": .02, "h60": 0., "h120": 0.})
        invvol = (1.0 / x["v20"]) / max(invmean, 1e-12) if s in data else 1.0
        raw[s] = max(score[s], .15) * (.94 + .06 * np.clip(invvol, .7, 1.3))
        if high_risk and s in DEFENSIVE:
            raw[s] *= 1.65
        if high_risk and x["h60"] < -.08 and s not in DEFENSIVE:
            raw[s] *= .88
        if high_risk and x["h120"] < -.12:
            raw[s] *= .90
    rebalance_to_weights(bounded(raw))

