            "macro": .14, "volstate": .12, "smooth": .10, "momentum": .08}
CLUSTERS = {
    "equity": {"000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX"},
    "commodity": {"XAU", "COPPER", "WTI"}, "crypto": {"BTC", "ETH"},
    "rates": {"US10Y", "CN10Y"}}
