import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = 0.03, 0.20
# Screener ensemble: medium excess momentum, trend consistency, breadth-confirmed momentum
FACTOR_W = (0.56, 0.23, 0.21)
_previous = None
_day = 0

def rank(vals):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / n if n else 0.5
    return out

def bounded(raw):
    # Iterative projection to a complete long-only target with explicit bounds.
    w = {s: max(float(raw.get(s, 1.0)), 1e-12) for s in UNIVERSE}
    fixed = set()
    for _ in range(30):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / max(z, 1e-12)
        hit = [s for s in free if w[s] < MIN_W or w[s] > MAX_W]
        if not hit:
            break
        for s in hit:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed.update(hit)
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return
    series = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=250)
        if df is None or len(df) < 140:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) < 140 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        # All features end at the last completed bar supplied by the simulator.
        series[s] = {
            "r": r, "h5": np.prod(1+r[-5:])-1, "h10": np.prod(1+r[-10:])-1,
            "h20": np.prod(1+r[-20:])-1, "h60": np.prod(1+r[-60:])-1,
            "h120": np.prod(1+r[-120:])-1, "v20": max(np.std(r[-20:]), .006)
        }
    if len(series) < 10:
        return
    med20 = np.median([x["h20"] for x in series.values()])
    med60 = np.median([x["h60"] for x in series.values()])
    breadth = np.mean([x["h20"] > 0 for x in series.values()])
    f1, f2, f3 = {}, {}, {}
    for s, x in series.items():
        # Excess momentum is deliberately medium horizon, not a 1-day timer.
        f1[s] = (x["h20"] - med20) / (x["v20"] * np.sqrt(20) + .02)
        # Consistency rewards positive returns on most of the last 20 sessions.
        f2[s] = np.mean(x["r"][-20:] > 0) + .25 * np.tanh(x["h60"] / (x["v20"] * 3 + .02))
        # Breadth confirmation scales medium momentum by market breadth.
        f3[s] = x["h20"] * (0.65 + 0.70 * breadth) + 0.35 * (x["h60"] - med60)
    ranks = [rank(f1), rank(f2), rank(f3)]
    score = {s: sum(w * q[s] for w, q in zip(FACTOR_W, ranks)) for s in UNIVERSE}
    if _previous is not None:
        score = {s: .65 * score[s] + .35 * _previous[s] for s in UNIVERSE}
    _previous = score.copy()
    median_vol = np.median([x["v20"] for x in series.values()])
    high_risk = median_vol > .018 or breadth < .45
    inv_avg = np.mean([1.0 / x["v20"] for x in series.values()])
    raw = {}
    for s in UNIVERSE:
        x = series.get(s, {"v20": median_vol, "h60": 0.0, "h120": 0.0})
        iv = (1.0 / x["v20"]) / max(inv_avg, 1e-12) if s in series else 1.0
        raw[s] = max(score[s], .12) * (.90 + .10 * np.clip(iv, .65, 1.35))
        if high_risk and s in DEFENSIVE:
            raw[s] *= 2.0
        # Do not chase weak momentum in an unstable regime; defensive assets remain eligible.
        if high_risk and s not in DEFENSIVE and x["h60"] < -.08:
            raw[s] *= .82
    rebalance_to_weights(bounded(raw))

