UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = 0.035, 0.18
# Current screener ensemble: consistency 49.8%, breakout 38.3%, medium excess momentum 11.9%.
FACTOR_W = (0.498, 0.383, 0.119)
_day = 0
_previous = None

def cross_rank(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / n
    return out

def project(raw):
    # Bounded, fully invested long-only projection.
    w = {s: max(float(raw.get(s, 1.0)), 1e-10) for s in UNIVERSE}
    fixed = set()
    for _ in range(40):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        total = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / max(total, 1e-12)
        hit = [s for s in free if w[s] < MIN_W or w[s] > MAX_W]
        if not hit:
            break
        for s in hit:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed.update(hit)
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 140:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) < 140 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), 0.006)
        data[s] = {"r": r, "v": v20,
                   "h20": float(np.prod(1+r[-20:])-1),
                   "h60": float(np.prod(1+r[-60:])-1),
                   "h120": float(np.prod(1+r[-120:])-1)}
    if len(data) < 10:
        return
    med20 = np.median([x["h20"] for x in data.values()])
    med60 = np.median([x["h60"] for x in data.values()])
    breadth = np.mean([x["h20"] > 0 for x in data.values()])
    consistency, breakout, excess = {}, {}, {}
    for s, x in data.items():
        # Trend consistency: persistence plus a modest medium-horizon trend term.
        consistency[s] = np.mean(x["r"][-20:] > 0) + 0.25 * np.tanh(x["h60"] / (3*x["v"] + .02))
        # Breakout60 volatility-normalized: distance from the 60-day baseline, damped by risk.
        breakout[s] = (x["h60"] - med60) / (x["v"] * np.sqrt(60) + .03)
        # Small weight, horizon-aligned excess momentum.
        excess[s] = (x["h20"] - med20) / (x["v"] * np.sqrt(20) + .02)
    rc, rb, re = map(cross_rank, (consistency, breakout, excess))
    score = {s: FACTOR_W[0]*rc[s] + FACTOR_W[1]*rb[s] + FACTOR_W[2]*re[s] for s in UNIVERSE}
    if _previous is not None:
        score = {s: .70*score[s] + .30*_previous[s] for s in UNIVERSE}
    _previous = score.copy()
    median_vol = float(np.median([x["v"] for x in data.values()]))
    high_risk = median_vol > .018 or breadth < .45
    inv_avg = np.mean([1.0/x["v"] for x in data.values()])
    raw = {}
    for s in UNIVERSE:
        x = data.get(s, {"v": median_vol, "h60": 0.0})
        iv = (1.0/x["v"])/max(inv_avg, 1e-12) if s in data else 1.0
        raw[s] = max(score[s], .10) * (.90 + .10*np.clip(iv, .65, 1.35))
        if high_risk and s in DEFENSIVE:
            raw[s] *= 2.0
        if high_risk and s not in DEFENSIVE and x["h60"] < -.08:
            raw[s] *= .82
    rebalance_to_weights(project(raw))

