import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = 0.025, 0.18
# Current Screener ensemble: downside-adjusted momentum, vol-normalized breakout, up-day dominance.
FACTOR_W = (0.60, 0.25, 0.15)
_day = 0
_previous = None

def cross_rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if good:
        n = len(good)
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out

def project(raw):
    # Simple bounded projection, retaining a complete 15-asset target.
    w = {s: max(float(raw.get(s, 1.0)), 1e-9) for s in UNIVERSE}
    fixed = set()
    for _ in range(40):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / max(z, 1e-12)
        hits = [s for s in free if w[s] < MIN_W or w[s] > MAX_W]
        if not hits:
            break
        for s in hits:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed.update(hits)
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 80:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) < 80 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        v = max(float(np.std(r[-20:])), 0.006)
        down = np.sqrt(np.mean(np.minimum(r[-20:], 0.0) ** 2))
        mom20 = np.prod(1.0 + r[-20:]) - 1.0
        # Breakout is measured against the prior 60-session high, excluding today.
        prior = c[-61:-1] if len(c) >= 61 else c[:-1]
        breakout = (c[-1] / max(np.max(prior), 1e-12) - 1.0) / max(v * np.sqrt(60), .01)
        data[s] = {"v": v, "down": max(down, .006),
                   "dm": mom20 / max(down, .006), "bo": breakout,
                   "up": float(np.mean(r[-30:] > 0)),
                   "h60": float(np.prod(1.0 + r[-60:]) - 1.0)}
    if len(data) < 10:
        return
    dm = cross_rank({s: x["dm"] for s, x in data.items()})
    bo = cross_rank({s: x["bo"] for s, x in data.items()})
    up = cross_rank({s: x["up"] for s, x in data.items()})
    score = {s: FACTOR_W[0]*dm[s] + FACTOR_W[1]*bo[s] + FACTOR_W[2]*up[s] for s in UNIVERSE}
    # Smooth only the composite score to reduce ten-day reversal turnover.
    if _previous is not None:
        score = {s: 0.70*score[s] + 0.30*_previous[s] for s in UNIVERSE}
    _previous = score.copy()
    medvol = float(np.median([x["v"] for x in data.values()]))
    breadth = float(np.mean([x["h60"] > 0 for x in data.values()]))
    high_risk = medvol > 0.018 or breadth < 0.45
    invmean = float(np.mean([1.0/x["v"] for x in data.values()]))
    raw = {}
    for s in UNIVERSE:
        x = data.get(s, {"v": medvol, "h60": 0.0})
        iv = (1.0/x["v"])/max(invmean, 1e-12) if s in data else 1.0
        raw[s] = max(score[s], 0.08) * (0.90 + 0.10*np.clip(iv, .65, 1.35))
        if high_risk and s in DEFENSIVE:
            raw[s] *= 2.0
        if high_risk and s not in DEFENSIVE and x["h60"] < -.08:
            raw[s] *= .82
    rebalance_to_weights(project(raw))

